package com.autocare.controller;import com.autocare.dto.request.*;import com.autocare.dto.response.*;import com.autocare.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/service-cases") public class ServiceCaseController {private final AppointmentService appointments;private final ServiceCaseWorkflowService workflow;public ServiceCaseController(AppointmentService a,ServiceCaseWorkflowService w){appointments=a;workflow=w;}@PostMapping("/walk-ins") public ResponseEntity<ServiceCaseResponse> walk(@Valid @RequestBody WalkInRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(appointments.walkIn(r));}@GetMapping public List<ServiceCaseDetailResponse> list(){return workflow.list();}@GetMapping("/{id}") public ServiceCaseDetailResponse get(@PathVariable String id){return workflow.get(id);}@PatchMapping("/{id}/priority") public ServiceCaseDetailResponse priority(@PathVariable String id,@Valid @RequestBody PriorityRequest r){return workflow.priority(id,r);}@PatchMapping("/{id}/assignment") public ServiceCaseDetailResponse assign(@PathVariable String id,@Valid @RequestBody AssignmentRequest r){return workflow.assign(id,r);}@PostMapping("/{id}/start-diagnosis") public ServiceCaseDetailResponse start(@PathVariable String id){return workflow.startDiagnosis(id);}@PostMapping("/{id}/submit-diagnosis") public ServiceCaseDetailResponse submit(@PathVariable String id){return workflow.submitDiagnosis(id);}@PutMapping("/{id}/diagnosis") public ServiceCaseDetailResponse diagnosis(@PathVariable String id,@Valid @RequestBody TextRequest r){return workflow.saveDiagnosis(id,r);}@PostMapping("/{id}/approve") public ServiceCaseDetailResponse approve(@PathVariable String id){return workflow.approve(id);}@PutMapping("/{id}/solution") public ServiceCaseDetailResponse solution(@PathVariable String id,@Valid @RequestBody TextRequest r){return workflow.solution(id,r);}@PutMapping("/{id}/notes") public ServiceCaseDetailResponse notes(@PathVariable String id,@Valid @RequestBody TextRequest r){return workflow.notes(id,r);}@PostMapping("/{id}/payment-pending") public ServiceCaseDetailResponse pay(@PathVariable String id){return workflow.payment(id);}@PostMapping("/{id}/ready-for-pickup") public ServiceCaseDetailResponse ready(@PathVariable String id){return workflow.ready(id);}@PostMapping("/{id}/hold") public ServiceCaseDetailResponse hold(@PathVariable String id){return workflow.hold(id);}@PostMapping("/{id}/cancel") public ServiceCaseDetailResponse cancel(@PathVariable String id){return workflow.cancel(id);}@GetMapping("/{id}/service-items") public List<ServiceItemResponse> items(@PathVariable String id){return workflow.items(id);}@PostMapping("/{id}/service-items") public ResponseEntity<ServiceItemResponse> item(@PathVariable String id,@Valid @RequestBody ServiceItemRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(workflow.addItem(id,r));}@DeleteMapping("/{id}/service-items/{itemId}") public ResponseEntity<Void> delete(@PathVariable String id,@PathVariable Long itemId){workflow.deleteItem(id,itemId);return ResponseEntity.noContent().build();}}
